function kimpu_register_preset_controls( $customizer ) {
	$section = 'kimpu_design_presets'; $customizer->add_section( $section, array( 'title' => __( 'Design Presets', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 10 ) ); $choices = array(); foreach ( kimpu_design_presets() as $key => $preset ) { $choices[ $key ] = $preset['label']; }
	$customizer->add_setting( 'kimpu_design_preset', array( 'default' => 'premium-emerald', 'sanitize_callback' => 'kimpu_design_allowed_preset', 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_preset', array( 'label' => __( 'Design Preset', 'kimpu-multipurpose' ), 'description' => __( 'Presets are an explicit visual mode. Choose Custom values when you want every individual color and typography control to take precedence.', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => $choices ) );
	if ( class_exists( 'KimPu_Design_Reset_Control' ) ) { $customizer->add_control( new KimPu_Design_Reset_Control( $customizer, 'kimpu_design_reset', array( 'section' => $section ) ) ); }
}

function kimpu_design_customizer_controls_assets() { wp_enqueue_script( 'kimpu-customizer-controls', get_template_directory_uri() . '/assets/js/customizer-controls.js', array( 'customize-controls' ), kimpu_asset_version( 'assets/js/customizer-controls.js' ), true ); }
add_action( 'customize_controls_enqueue_scripts', 'kimpu_design_customizer_controls_assets' );
